/// <summary>/// Report Data Provider class for the SKL Sample Customer Report./// </summary>
[
// REMOVED: SRSReportQueryAttribute(queryStr(SKL_SampleCustomerQuery))
// We only need the parameter attribute now to link the contract.
SRSReportParameterAttribute(classStr(SKL_SampleReportContract))
]public class SKL_SampleReportDP extends SRSReportDataProviderBase
{
    SKL_SampleCustomer tempSKL_SampleCustomer;

}

Method.Source:
[SRSReportDataSetAttribute(tableStr(SKL_SampleCustomer))]
public SKL_SampleCustomer getSKL_SampleCustomer()
{
    select tempSKL_SampleCustomer;
    return tempSKL_SampleCustomer;
}

/// <summary>
/// Core business logic to read data and populate our TempDB table.
/// </summary>
public void processReport()
{
    CustTable custTable;

    // Clear the temporary buffer before starting
    tempSKL_SampleCustomer.clear();

    // Loop through ALL customers (no 'where' clause!)
    while select custTable
    {
        // Map data fields from master table to our report table
        tempSKL_SampleCustomer.AccountNum = custTable.AccountNum;
        tempSKL_SampleCustomer.Name = custTable.name();
        tempSKL_SampleCustomer.Balance = custTable.openBalanceMST();

        // Insert into our TempDB table cache
        tempSKL_SampleCustomer.insert();
    }
}
